using System.Text; using GymManagement.Api.Data; using Microsoft.AspNetCore.Authentication.JwtBearer; using Microsoft.EntityFrameworkCore; using Microsoft.IdentityModel.Tokens;
var builder = WebApplication.CreateBuilder(args); builder.Services.AddDbContext<GymDbContext>(o=>o.UseSqlServer(builder.Configuration.GetConnectionString("DefaultConnection"))); builder.Services.AddControllers(); builder.Services.AddEndpointsApiExplorer(); builder.Services.AddSwaggerGen(); var key=builder.Configuration["Jwt:Key"]!; builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new(){ValidateIssuer=true,ValidateAudience=true,ValidateLifetime=true,ValidateIssuerSigningKey=true,ValidIssuer=builder.Configuration["Jwt:Issuer"],ValidAudience=builder.Configuration["Jwt:Audience"],IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key))}); builder.Services.AddAuthorization(); var app=builder.Build(); app.UseSwagger();app.UseSwaggerUI();app.UseHttpsRedirection();app.UseAuthentication();app.UseAuthorization();app.MapControllers();using(var s=app.Services.CreateScope())await DbSeeder.SeedAsync(s.ServiceProvider);app.Run();
